UPDATE knowledge_document
SET index_status = 'FAILED', index_failure_reason = #{reason}
WHERE id = #{documentId}

UPDATE knowledge_document
SET publish_status = 'DISABLED'
WHERE logical_document_code = #{logicalDocumentCode}
  AND id != #{excludingId}
  AND publish_status = 'PUBLISHED'

UPDATE knowledge_document
SET publish_status = 'PUBLISHED'
WHERE id = #{documentId}
